#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll INF = LLONG_MAX;

int n, m;
vector<vector<pair<int, ll>>> g;

vector<ll> dijkstra(int src) {
    vector<ll> dist(n, INF);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : g[u])
            if (d + w < dist[v]) { dist[v] = d + w; pq.push({dist[v], v}); }
    }
    return dist;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    g.assign(n, {});
    for (int i = 0; i < m; i++) {
        int u, v;
        ll w;
        cin >> u >> v >> w;
        g[u].push_back({v, w}); // directed edge u -> v
    }
    int start, target, waypoint;
    cin >> start >> target >> waypoint;
    vector<ll> fromStart = dijkstra(start), fromWay = dijkstra(waypoint);
    ll direct = fromStart[target] == INF ? -1 : fromStart[target];
    ll via = (fromStart[waypoint] == INF || fromWay[target] == INF) ? -1 : fromStart[waypoint] + fromWay[target];
    cout << direct << " " << via << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    static int n, m;
    static int[] head, nxt, to;
    static long[] wt;

    static long[] dijkstra(int src) {
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[src] = 0;
        // heap entries pack (distance, node) as two longs
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        pq.add(new long[]{0, src});
        while (!pq.isEmpty()) {
            long[] top = pq.poll();
            long d = top[0];
            int u = (int) top[1];
            if (d != dist[u]) continue;
            for (int e = head[u]; e >= 0; e = nxt[e]) {
                int v = to[e];
                if (d + wt[e] < dist[v]) { dist[v] = d + wt[e]; pq.add(new long[]{dist[v], v}); }
            }
        }
        return dist;
    }

    public static void main(String[] args) throws IOException {
        n = (int) nextLong();
        m = (int) nextLong();
        head = new int[n];
        Arrays.fill(head, -1);
        nxt = new int[m];
        to = new int[m];
        wt = new long[m];
        for (int i = 0; i < m; i++) {
            int u = (int) nextLong();
            to[i] = (int) nextLong();
            wt[i] = nextLong();
            nxt[i] = head[u]; // directed edge u -> v
            head[u] = i;
        }
        int start = (int) nextLong(), target = (int) nextLong(), waypoint = (int) nextLong();
        long[] fromStart = dijkstra(start), fromWay = dijkstra(waypoint);
        long direct = fromStart[target] == Long.MAX_VALUE ? -1 : fromStart[target];
        long via = (fromStart[waypoint] == Long.MAX_VALUE || fromWay[target] == Long.MAX_VALUE) ? -1 : fromStart[waypoint] + fromWay[target];
        System.out.println(direct + " " + via);
    }
}
